namespace ghidra.util.datastruct;

using static org.junit.Assert;



using org.junit;

using generic.test;

public class WeakStoreTest : AbstractGenericTest {
	/* @Test */
	public void testStore() {
		WeakStore<Foo> store = new();
		store.add(new Foo("AAA"));
		store.add(new Foo("BBB"));
		store.add(new Foo("CCC"));

		assertEquals(3, store.size());

		List<Foo> values = store.getValues();

		assertEquals("AAA", values.get(0).getName());
		assertEquals("BBB", values.get(1).getName());
		assertEquals("CCC", values.get(2).getName());
		values = null;

		waitFor(() => {
			System.gc();
			return store.size() == 0;
		}, "Weak store values were never garbage collected");
	}

	static class Foo {
		string name;

		Foo(string name) {
			this.name = name;
		}

		string getName() {
			return name;
		}
	}

}
